<template>
  <main class="platform-menu-page">
    <section v-for="screen in screens" :key="screen.key">
      <header class="heading"><div><h1>平台权限规则</h1><p>管理平台菜单与接口规则，核对旧数字角色的引用。</p></div><div class="actions"><el-button :disabled="!canView || state.busy || state.loading" @click="screen.refresh">重新读取目录</el-button><el-button v-if="canManage" type="primary" :disabled="!model.writable()" @click="screen.create">添加规则</el-button></div></header>
      <el-alert v-if="state.pending" title="原操作结果尚未确认，新的编辑与提交已暂停" type="warning" :closable="false"><p>请先读取原请求回执。回执暂未找到时，可以主动原样重试。</p><div class="actions"><el-button :disabled="state.busy" @click="screen.receipt">读取原请求回执</el-button><el-button v-if="state.retryReady && canManage" :disabled="state.busy" @click="screen.retry">原样重试</el-button></div></el-alert>
      <el-alert v-if="!canView || state.revoked" title="当前没有平台权限规则查看权限，请重新登录或联系管理员" type="warning" :closable="false" />
      <el-alert v-if="state.error || state.pendingError" :title="state.error || state.pendingError" type="error" :closable="false" />
      <el-alert v-if="state.notice" :title="state.notice" type="info" :closable="false" />
      <template v-if="canView && !state.revoked">
        <el-alert v-if="state.snapshot && !state.snapshot.write_ready" title="此环境尚未安装平台规则受控写入能力，目录可查看" type="warning" :closable="false" />
        <p class="hint">仅超级管理员可修改。角色引用包含停用和未分配角色。当前后台导航由固定目录生成。</p>
        <div class="filters"><label>显示状态<el-select :model-value="filters.show" aria-label="筛选显示状态" :disabled="viewLocked" @update:model-value="screen.show"><el-option label="全部状态" :value="-1" /><el-option label="显示" :value="1" /><el-option label="隐藏" :value="0" /></el-select></label><label>规则搜索<el-input :model-value="filters.keyword" aria-label="规则搜索" placeholder="名称、接口、路径、权限标识或ID" clearable :disabled="viewLocked" @update:model-value="screen.keyword" /></label><el-button :disabled="viewLocked" @click="screen.reset">重置筛选</el-button></div>
        <p class="hint">完整目录 {{ state.snapshot?.count ?? 0 }} 项，筛选后 {{ visible.length }} 项。</p>
        <p v-if="state.loading" role="status">正在读取完整规则目录…</p>
        <div v-if="state.ready" class="rows" aria-label="平台权限规则列表">
          <article v-for="item in rows" :key="item.key" class="rule-row"><div class="rule-info" :style="{paddingLeft:`${item.node.depth * 12}px`}"><el-button v-if="item.node.children.length && !item.node.issue" text :disabled="viewLocked" :aria-label="`${item.collapsed ? '展开' : '收起'}规则 ${item.row.menu_name}`" @click="item.toggle">{{ item.collapsed ? '＋' : '－' }}</el-button><strong>{{ item.row.menu_name || '未命名历史规则' }}</strong><el-tag size="small">{{ item.row.auth_type === 1 ? '菜单' : item.row.auth_type === 2 ? '接口' : `历史类型 ${item.row.auth_type}` }}</el-tag><p>#{{ item.row.id }} · 父级 #{{ item.row.pid }} · 排序 {{ item.row.sort }} · {{ item.row.is_show ? '显示' : '隐藏' }}</p><p v-if="item.row.auth_type === 2">{{ item.row.methods || '历史空方法' }} {{ item.row.api_url }}</p><p v-else>{{ item.row.menu_path }} <span v-if="item.row.unique_auth">· {{ item.row.unique_auth }}</span></p><p v-if="item.node.issue" class="issue">{{ item.node.issue }}，请显式选择有效父级。</p><p>角色引用：{{ item.row.role_reference_ids.join('、') || '无' }}</p></div><div v-if="canManage" class="actions"><el-button v-if="item.row.auth_type === 1" :disabled="!model.writable()" @click="item.child">添加子规则</el-button><el-button :disabled="!model.writable()" @click="item.edit">编辑</el-button><el-button v-if="item.row.auth_type === 1" :disabled="!model.writable()" @click="item.row.is_show ? item.hide() : item.show()">{{ item.row.is_show ? '隐藏' : '显示' }}</el-button><el-button type="danger" plain :disabled="!model.writable()" @click="item.remove">删除</el-button></div></article>
          <p v-if="!visible.length" class="empty">没有符合条件的规则</p>
        </div>
        <nav class="actions pagination" aria-label="规则分页"><span>第 {{ filters.page }} / {{ pageCount }} 页，每页20项</span><el-button :disabled="viewLocked || filters.page <= 1" @click="screen.previous">上一页</el-button><el-button :disabled="viewLocked || filters.page >= pageCount" @click="screen.next">下一页</el-button></nav>
      </template>
    </section>
    <el-dialog v-for="editor in editors" :key="editor.key" :model-value="true" :title="state.editor?.original ? '编辑权限规则' : '添加权限规则'" width="min(680px, calc(100vw - 24px))" :close-on-click-modal="false" :close-on-press-escape="false" :show-close="false" :destroy-on-close="true">
      <el-alert v-if="state.error" :title="state.error" type="error" :closable="false" />
      <el-alert v-if="state.editor?.original?.role_reference_ids.length" title="该规则已有角色引用，授权字段须原样保留" type="warning" :closable="false" />
      <el-form label-position="top" :disabled="!model.writable()">
        <template v-for="field in editor.fields" :key="field.key">
          <el-form-item v-if="fieldVisible(field.field)" :label="labels[field.field]">
            <el-select v-if="field.field === 'auth_type'" :model-value="field.value" aria-label="规则类型" @update:model-value="field.set"><el-option label="菜单" :value="1" /><el-option label="接口" :value="2" /><el-option v-if="field.value === 0" label="历史类型0（请显式选择）" :value="0" /></el-select>
            <el-select v-else-if="field.field === 'pid'" :model-value="field.value" aria-label="父级菜单" filterable @update:model-value="field.set"><el-option v-for="parent in editor.parents" :key="parent.id" :value="parent.id" :label="parent.label" :disabled="parent.disabled" /></el-select>
            <el-select v-else-if="field.field === 'methods'" :model-value="field.value" aria-label="请求方式" @update:model-value="field.set"><el-option label="请选择" value="" /><el-option v-for="method in ['GET','POST','PUT','DELETE']" :key="method" :label="method" :value="method" /><el-option v-if="field.value && !['GET','POST','PUT','DELETE'].includes(String(field.value))" :label="`历史方法 ${field.value}`" :value="field.value" /></el-select>
            <el-select v-else-if="field.field === 'is_show' || field.field === 'is_show_path'" :model-value="field.value" :aria-label="labels[field.field]" @update:model-value="field.set"><el-option :label="field.field === 'is_show' ? '显示' : '是'" :value="1" /><el-option :label="field.field === 'is_show' ? '隐藏' : '否'" :value="0" /></el-select>
            <el-input-number v-else-if="field.field === 'sort'" :model-value="Number(field.value)" aria-label="排序" :min="Math.min(0,state.editor?.original?.sort ?? 0)" :max="2147483647" :precision="0" @update:model-value="field.set" />
            <el-select v-else-if="field.field === 'menu_path'" :model-value="field.value" aria-label="页面路由" filterable allow-create default-first-option @update:model-value="field.set"><el-option v-for="page in state.snapshot?.pages ?? []" :key="page.path" :label="`${page.name} ${page.path}`" :value="page.path" /><el-option v-if="field.value && !state.snapshot?.pages.some(p=>p.path===field.value)" :value="field.value" :label="`保留历史路径 ${field.value}`" /></el-select>
            <template v-else-if="field.field === 'icon'"><el-input :model-value="String(field.value)" aria-label="图标符号" readonly /><details class="picker"><summary>选择图标</summary><el-input :model-value="editor.iconSearch" aria-label="搜索图标" @update:model-value="editor.searchIcon" /><div class="actions"><el-button v-for="icon in icons.filter(i=>i.includes(editor.iconSearch))" :key="icon" :disabled="!model.writable()" @click="field.set(icon)">{{ icon || '不使用图标' }}</el-button></div></details></template>
            <el-input v-else :model-value="String(field.value)" :aria-label="labels[field.field]" @update:model-value="field.set" />
          </el-form-item>
        </template>
        <details v-if="state.editor?.draft.auth_type === 2" class="picker"><summary>从已注册接口目录选择</summary><el-input :model-value="editor.apiSearch" aria-label="搜索接口目录" placeholder="接口名称、路径、请求方式或权限" @update:model-value="editor.searchApi" /><el-button :disabled="!model.writable()" @click="editor.searchApi('')">重置接口搜索</el-button><p class="hint">仅显示尚未添加的当前 Admin 接口。选择后填入名称、方法和路径。</p><div class="api-options"><el-button v-for="api in filteredApis(editor.apiSearch)" :key="api.method + api.rule" :disabled="!model.writable()" @click="editor.chooseApi(api)">{{ api.real_name }}</el-button></div></details>
      </el-form>
      <p class="hint">接口规则保存为显示状态。未显示的历史元数据和另一类字段会原值保留。</p>
      <template #footer><div class="actions"><template v-for="screen in screens" :key="screen.key"><el-button v-if="state.pending" :disabled="state.busy" @click="screen.receipt">读取原请求回执</el-button><el-button v-if="state.pending && state.retryReady && canManage" :disabled="state.busy" @click="screen.retry">原样重试</el-button></template><el-button :disabled="state.busy || !!state.pending" @click="editor.close">取消</el-button><el-button type="primary" :disabled="!model.writable()" :loading="state.busy" @click="editor.submit">保存规则</el-button></div></template>
    </el-dialog>
    <el-dialog v-for="confirmation in confirmations" :key="confirmation.key" :model-value="true" title="删除权限规则" width="min(440px, calc(100vw - 24px))" :close-on-click-modal="false" :close-on-press-escape="false" :show-close="false"><p>确认删除「{{ confirmation.row.menu_name }}」（#{{ confirmation.row.id }}）？有子级或角色引用时不能删除。</p><el-alert v-if="state.error" :title="state.error" type="error" :closable="false" /><template #footer><div class="actions"><template v-for="screen in screens" :key="screen.key"><el-button v-if="state.pending" :disabled="state.busy" @click="screen.receipt">读取原请求回执</el-button></template><el-button :disabled="state.busy || !!state.pending" @click="confirmation.cancel">取消</el-button><el-button type="danger" :disabled="!model.writable()" @click="confirmation.confirm">确认删除</el-button></div></template></el-dialog>
  </main>
</template>
<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,watch} from 'vue';
import {useRoute} from 'vue-router';
import {useAuthStore} from '@/stores/auth';
import {getAdminSession,getToken} from '@/utils/auth';
import {apiPlatformMenuCatalog,apiPlatformMenuWrite,apiPlatformMenuReceipt} from '@/api/platformMenus';
import {platformMenuState} from '@/utils/platformMenuState';
import {PLATFORM_MENU_ICONS,platformMenuGraph,type PlatformMenuAction,type PlatformMenuValues} from '../../../../common/platformMenuRules';
const auth=useAuthStore(),route=useRoute();let generation=0,alive=false,syncing=false,queued=false;
const canView=computed(()=>!!auth.token&&auth.token===getToken()&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('system_menu_rules.view')||auth.uniqueAuth.includes('system_menu_rules.manage')));
const canManage=computed(()=>canView.value&&auth.userInfo?.level===0);
const prefix=(actor:number)=>`cinashop_platform_menu_pending_v1_${actor}_`;
function keys(actor:number){const result:string[]=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith(prefix(actor)))result.push(key);}return result.sort();}
const model=platformMenuState({identity:()=>`${generation}:${auth.token}:${auth.userInfo?.id}`,actor:()=>auth.userInfo?.id??0,view:()=>canView.value,manage:()=>canManage.value,read:apiPlatformMenuCatalog,write:apiPlatformMenuWrite,receipt:apiPlatformMenuReceipt,
 readPending:actor=>{const key=keys(actor)[0];if(!key)return null;const raw=localStorage.getItem(key);if(!raw||raw.length>65536)throw Error('本机未确认操作记录异常，请保留并核对');const v=JSON.parse(raw);if(key!==prefix(actor)+v?.input?.request_id)throw Error('未确认请求标识不一致');return v;},
 persist:(actor:number,action:PlatformMenuAction|null,expected?:PlatformMenuAction)=>{const a=action??expected;if(!a)throw Error('缺少原操作标识');const key=prefix(actor)+a.input.request_id,raw=localStorage.getItem(key);if(action){if(keys(actor).some(k=>k!==key))throw Error('本账号另有未确认权限规则操作');if(raw&&raw!==JSON.stringify(action))throw Error('原操作记录已变化');localStorage.setItem(key,JSON.stringify(action));}else{if(raw&&raw!==JSON.stringify(expected))throw Error('原操作记录不一致，不能清除');localStorage.removeItem(key);}},
},v=>reactive(v) as typeof v);
const state=model.state,filters=reactive({show:-1,keyword:'',page:1}),icons=PLATFORM_MENU_ICONS,collapsed=reactive(new Set<number>());
const graph=computed(()=>platformMenuGraph(state.snapshot?.list??[]));
const viewLocked=computed(()=>state.busy||state.loading||!!state.pending||!!state.editor||!!state.confirmation||!state.ready);
const visible=computed(()=>{const key=filters.keyword.toLocaleLowerCase(),pattern=new RegExp(key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replaceAll('%','.*').replaceAll('_','.'),'iu'),list=state.snapshot?.list??[];if(key||filters.show>=0)return list.filter(r=>(filters.show<0||r.is_show===filters.show)&&(!key||[r.menu_name,r.menu_path,r.unique_auth,r.api_url,String(r.id),String(r.pid)].some(v=>pattern.test(v))));const by=new Map(list.map(r=>[r.id,r])),stack=list.filter(r=>!r.pid&&!graph.value.get(r.id)!.issue).reverse(),out=[] as typeof list;while(stack.length){const r=stack.pop()!;out.push(r);if(!collapsed.has(r.id))for(const id of [...graph.value.get(r.id)!.children].reverse()){const child=by.get(id)!;if(!graph.value.get(id)!.issue)stack.push(child);}}return [...out,...list.filter(r=>graph.value.get(r.id)!.issue)];});
const pageCount=computed(()=>Math.max(1,Math.ceil(visible.value.length/20))),rows=computed(()=>visible.value.slice((filters.page-1)*20,filters.page*20).map(r=>{const epoch=state.epoch,source=state.sourceVersion;return {...model.rowControls(r),node:graph.value.get(r.id)!,collapsed:collapsed.has(r.id),toggle:()=>{if(epoch!==state.epoch||source!==state.sourceVersion||viewLocked.value||!model.retireView())return;if(collapsed.has(r.id))collapsed.delete(r.id);else collapsed.add(r.id);filters.page=1;}};}));
const screens=computed(()=>model.pageControls().map(c=>{const epoch=state.epoch,source=state.sourceVersion,snapshot=state.snapshot;const change=(fn:()=>void)=>{if(epoch===state.epoch&&source===state.sourceVersion&&!viewLocked.value&&model.retireView())fn();};return {...c,show:(v:unknown)=>change(()=>{if(typeof v==='number'&&[-1,0,1].includes(v)){filters.show=v;filters.page=1;}}),keyword:(v:unknown)=>{if(epoch===state.epoch&&snapshot===state.snapshot&&!viewLocked.value&&typeof v==='string'&&model.retireView()){filters.keyword=v;filters.page=1;}},reset:()=>change(()=>{filters.show=-1;filters.keyword='';filters.page=1;}),previous:()=>change(()=>{filters.page=Math.max(1,filters.page-1);}),next:()=>change(()=>{filters.page=Math.min(pageCount.value,filters.page+1);})};}));
const editors=computed(()=>model.editorControls()),confirmations=computed(()=>model.confirmationControls());
const labels:Record<keyof PlatformMenuValues,string>={pid:'父级菜单',auth_type:'规则类型',menu_name:'规则名称',menu_path:'页面路由',unique_auth:'前端权限标识',api_url:'接口地址',methods:'请求方式',icon:'图标符号',sort:'排序',is_show:'显示状态',is_show_path:'隐藏路径'};
const fieldVisible=(k:keyof PlatformMenuValues)=>['methods','api_url'].includes(k)?state.editor?.draft.auth_type===2:['menu_path','unique_auth','icon','is_show_path'].includes(k)?state.editor?.draft.auth_type===1:true;
const filteredApis=(search:string)=>(state.snapshot?.apis??[]).filter(a=>`${a.real_name} ${a.permission}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()));
function schedule(){if(!alive||syncing)return;generation++;model.dispose();if(queued)return;queued=true;queueMicrotask(()=>{queued=false;if(alive)void model.activate();});}
function syncStored(event?:Event){if(syncing||event instanceof StorageEvent&&event.key!==null&&!['admin_token','admin_session'].includes(event.key))return;syncing=true;generation++;model.dispose();const session=getAdminSession();auth.$patch({token:getToken()??'',userInfo:session?.userInfo??null,menus:(session?.menus as typeof auth.menus)??[],uniqueAuth:session?.uniqueAuth??[]});syncing=false;schedule();}
watch(()=>[auth.token,auth.userInfo,auth.uniqueAuth,auth.menus],schedule,{deep:true,flush:'sync'});
watch(()=>route.fullPath,schedule,{flush:'sync'});
const stopAction=auth.$onAction(({name,after})=>{if(name==='login'||name==='logout')after(schedule);});
onMounted(()=>{alive=true;window.addEventListener('storage',syncStored);window.addEventListener('admin-session-changed',syncStored);window.addEventListener('admin-auth-expired',syncStored);syncStored();});
onBeforeUnmount(()=>{alive=false;generation++;stopAction();model.dispose();window.removeEventListener('storage',syncStored);window.removeEventListener('admin-session-changed',syncStored);window.removeEventListener('admin-auth-expired',syncStored);});
</script>
<style scoped>
.platform-menu-page,.platform-menu-page>section{display:grid;gap:16px;min-width:0}.heading,.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.heading{justify-content:space-between}.heading h1{font-size:22px;margin:0}.heading p,.hint,.rule-info p{font-size:13px;line-height:1.7;color:var(--el-text-color-secondary);margin:6px 0}.filters{display:grid;grid-template-columns:180px minmax(180px,1fr) auto;gap:12px;align-items:end}.filters label{display:grid;gap:8px;font-size:14px}.actions .el-button+.el-button{margin-left:0}.rows{border:1px solid var(--el-border-color);border-radius:6px}.rule-row{display:flex;justify-content:space-between;gap:20px;padding:16px}.rule-row+.rule-row{border-top:1px solid var(--el-border-color-lighter)}.rule-info{min-width:0;overflow-wrap:anywhere}.issue{color:var(--el-color-warning-dark-2)!important}.rule-info strong{margin-right:8px}.pagination{justify-content:flex-end;font-size:13px}.empty{padding:24px}.picker{width:100%;margin:12px 0;min-width:0}.picker summary{cursor:pointer;margin-bottom:12px;color:var(--el-color-primary)}.picker .actions{margin-top:12px;max-height:220px;overflow:auto}.api-options{display:grid;gap:8px;max-height:240px;overflow:auto;margin-top:12px}.api-options .el-button{height:auto;white-space:normal;justify-content:flex-start;margin:0;padding:10px;text-align:left}.platform-menu-page :deep(.el-select){width:100%}.platform-menu-page :deep(.el-alert__content){overflow-wrap:anywhere;min-width:0}@media(max-width:900px){.rule-row{flex-direction:column}.filters{grid-template-columns:1fr 2fr}.filters>.el-button{justify-self:start}}@media(max-width:480px){.filters{grid-template-columns:1fr}.heading>.actions{width:100%}.rule-row{padding:12px}.rule-info{padding-left:0!important}.pagination{justify-content:flex-start}}
</style>
